    ticketHelp: {
      rowTitle: 'Tickets et imprimante',
      rowSub: 'Imprimer, réimprimer, corriger',
      intro: 'Chaque commande a un ticket au format caisse : client, type (livraison, à emporter, sur place), articles avec quantités et prix, note du client, total, code de retrait ou de livraison. Il sort sur ton imprimante thermique ou par la boîte d\'impression de ton appareil.',
      howTitle: 'Imprimer un ticket, pas à pas',
      how1: 'Ouvre l\'application Fairide (installée sur ta tablette, ton téléphone ou ton PC), allume ton imprimante thermique Bluetooth et va dans Commandes.',
      how2: 'Dans la carte « Imprimante à tickets », touche « Connecter mon imprimante » et choisis-la dans la liste. À refaire quand tu rouvres l\'application : c\'est le système qui l\'impose, pas Fairide.',
      how3: 'Imprime un ticket de test : s\'il sort, tout est prêt. Choisis le papier (58 ou 80 mm) selon ton imprimante.',
      how4: 'Ensuite, le bouton 🖨️ sur chaque commande imprime son ticket en un clic ; le détail de la commande propose aussi « Imprimer le ticket », « ×2 » et « Imprimer le bon de livraison ».',
      autoTitle: 'Impression automatique',
      auto1: 'Coche « Imprimer automatiquement chaque nouvelle commande » dans la carte Imprimante : chaque commande payée sort dès son arrivée, sans rien toucher.',
      auto2: 'Garde l\'onglet Commandes ouvert et l\'imprimante connectée pendant le service. Une commande n\'est jamais imprimée deux fois automatiquement.',
      editTitle: 'Réimprimer, corriger, créer un ticket',
      edit1: 'Première sortie ratée (papier coincé, imprimante éteinte) ? Ouvre la commande et clique « Imprimer à nouveau » autant de fois que nécessaire ; le détail indique combien de fois le ticket est déjà sorti. Rien ne change pour la commande.',
      edit2: '« Modifier le ticket » ouvre l\'éditeur : corrige un libellé, retire ou ajoute une ligne, ajoute une note (allergie, sans oignons…), choisis le nombre de copies, puis imprime. La commande enregistrée reste intacte, seul le papier change.',
      edit3: '« Nouveau ticket manuel » (carte Imprimante) crée un ticket de zéro : commande par téléphone, table sur place, bon de cuisine. Il s\'imprime en Bluetooth ou par la boîte d\'impression ; il n\'est pas enregistré comme commande.',
      deviceTitle: 'Quel appareil, quelle imprimante',
      device1: 'Bluetooth direct depuis l\'application : tablette ou téléphone Android, PC Windows, Mac ou Chromebook (application installée depuis Chrome ou Edge). Imprimante thermique ESC/POS en Bluetooth Low Energy (BLE), papier 58 ou 80 mm (Xprinter, Munbyn, Goojprt, Netum, Phomemo, modèles « BLE »).',
      device2: 'iPad et iPhone : l\'application web n\'a pas accès au Bluetooth (limite d\'Apple). Dès le 6 octobre 2026, l\'application Fairide de l\'App Store imprimera en Bluetooth directement. D\'ici là : « Imprimer le bon de livraison » avec une imprimante AirPrint ou Wi-Fi, ou une tablette Android au comptoir pour l\'imprimante thermique.',
      device3: 'Imprimante USB, Wi-Fi ou réseau (Epson, Star…) : installe-la sur l\'appareil comme n\'importe quelle imprimante, puis « Imprimer le bon de livraison ». Sur Android, l\'appli gratuite RawBT envoie aussi le ticket vers une imprimante thermique.',
      troubleTitle: 'Ça ne sort pas ?',
      trouble1: 'L\'imprimante n\'apparaît pas dans la liste : vérifie qu\'elle est allumée, en BLE (pas Bluetooth classique), et qu\'elle n\'est pas déjà appairée à un autre appareil.',
      trouble2: '« Aucune imprimante connectée » après un rechargement : c\'est normal, reconnecte-la en un clic.',
      trouble3: 'Ticket tronqué ou caractères bizarres : passe en 58 mm si l\'imprimante est petite, et vérifie le rouleau.',
      trouble4: 'Toujours rien : « Imprimer le bon de livraison » passe par la boîte d\'impression de l\'appareil et marche avec n\'importe quelle imprimante installée. Et écris-nous depuis Assistance.',
      contentTitle: 'Ce que contient le ticket',
      contentText: 'Nom du commerce et adresse, numéro et heure de la commande, type, client et téléphone, articles avec quantités et prix, note et instructions du client, sous-total, livraison, remise, total, code de retrait ou de livraison. Les accents sont simplifiés sur le ticket thermique (« Creme brulee ») pour rester lisibles sur tous les modèles.',
      goOrders: 'Ouvrir la page Commandes →'
    },
